WFJ.Data.add("quest", {
  [90116] = { "Fili sacri", "Ottieni dei Dawnwoven Fabric tessendo stoffa in rotoli vicino al Crusader's Loom. Torna da Taylor quando ne avrai abbastanza.", "Questo telaio è speciale. Lo sapevi? Tutti i nostri artigiani hanno fatto benedire gli attrezzi del mestiere dai nostri sommi sacerdoti.\n\nIn particolare, il telaio attira stoffe e fili sparsi destinati ai più sacri dei nostri paramenti cerimoniali. Col tempo ne raccoglieremo abbastanza per creare una nuova veste, e quei giorni sono motivo di festa, almeno per me.\n\nSe il procedimento ti incuriosisce, tessi qualche rotolo vicino al telaio e guarda la Luce all'opera.", nil, nil, 0xc5231693, 0x64619cbd, 0x049e6b14, nil, nil, "...mm" },
  [90487] = { "Antichi alleati", "Viaggia a ovest dalla grotta dell'eremita per trovare un avamposto di antichi e driadi sulle pendici basse del ⟦Mount Hyjal=Monte Hyjal⟧.", nil, nil, nil, 0x00eda785, 0xe01cf952, nil, nil, nil, "..mmm" },
  [90647] = { "Bastone della Montagna", "Porta il Bastone della Montagna a Tiala Biancachioma alla Vetta dell'Eternità.", nil, nil, nil, 0x9af96789, 0x16e85ed9, nil, nil, nil, "..mmm" },
  [90702] = { "Tomba profanata", "Cerca nei dintorni il contenuto mancante della tomba.", nil, nil, nil, 0x122854ff, 0xee590106, nil, nil, nil, "..mmm" },
  [90750] = { "Ancora lavoro?", "Parla con il contadino per fargli sapere che il lavoro è finito.", nil, nil, nil, 0x4489f9ed, 0x38a33249, nil, nil, nil, "..mmm" },
  [90789] = { "⟦Scalebeard=Barbascaglia⟧", "Recupera la ⟦Prismatic Shell=Conchiglia Prismatica⟧ per l'⟦Archmage Xylem=Arcimago Xylem⟧. L'arcimago risiede in una torre in cima alle scogliere di Azshara.", nil, nil, nil, 0xcd852ff9, 0xe0e3c89c, nil, nil, nil, "..mmm" },
  [90813] = { "Filone fortunato!", "Trova qualcuno che possa valutare il Cristallo Enorme.", nil, nil, nil, 0x89afa7ee, 0x45a72cf5, nil, nil, nil, "..mmm" },
  [90854] = { "Cuoio per il maltempo", "Porta $N1 Potenziamento d'Armatura Duro e $N2 ⟦Cured Rugged Hide=Pelle Dura Trattata⟧ a Zet'gan nella Selva Antica, sul ⟦Mount Hyjal=Monte Hyjal⟧.", nil, nil, nil, 0x8cba0394, 0x1cb3933a, nil, nil, nil, "..mmm" },
